using System;using System.IO;using HdrPilot;
class AsiCheck{
static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
static void Main(string[] a){string d=a[0];Core.Data=Path.Combine(d,"testdata");Directory.CreateDirectory(Core.Data);string root=Path.Combine(d,"game");Directory.CreateDirectory(root);File.Copy(Path.Combine(d,"HDLSS5-test.exe"),Path.Combine(root,"game.exe"),true);var g=new Game{Id="asi-test",Name="Fixture",Root=root,Exe=Path.Combine(root,"game.exe")};string old=Path.Combine(d,"old","dinput8.dll");Check(AsiLoader.IsLoader(old),"old loader rejected");string current=AsiLoader.Extract(Path.Combine(d,"asi.zip"));Check(AsiLoader.IsLoader(current),"10 rejected");Check(!AsiLoader.IsLoader(g.Exe),"unrelated PE accepted");string fake=Path.Combine(d,"fake32.dll");byte[] bytes=File.ReadAllBytes(current);int offset=BitConverter.ToInt32(bytes,60);bytes[offset+4]=0x4c;bytes[offset+5]=0x01;File.WriteAllBytes(fake,bytes);Check(!AsiLoader.IsLoader(fake),"32bit accepted");string dest=Path.Combine(root,"winmm.dll");File.Copy(old,dest,true);string before=DlssCore.Hash(dest);var plan=AsiLoader.Prepare(g,current,"dinput8.dll");Check(plan.Changes[0].Name=="winmm.dll","installed name changed");DlssCore.Apply(g,plan);Check(DlssCore.Hash(dest)==DlssCore.Hash(current),"update failed");Check(AsiLoader.Installed(g).Length==1,"installed 10 not detected");DlssCore.Apply(g,AsiLoader.Restore(g));Check(DlssCore.Hash(dest)==before,"9.7.4 not restored");File.WriteAllText(Path.Combine(d,"asi-tests-passed.txt"),"PASS official 9.7.4 and 10.0.0; reject unrelated and x86 PE; update existing winmm.dll; recognize installed v10; restore original 9.7.4 byte-for-byte.");}}
